+    // Auto-vectorized Java shifts mask the count to 0..31.
+    static final int SHIFT = 32;
+    static final byte[] DST_L = new byte[SHIFT * LENGTH];
+    static final byte[] DST_A = new byte[SHIFT * LENGTH];
